<?php
$title='Pharmacies de garde';$nav='/admin/pharmacies-de-garde';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='pharmacy'){GuardPharmacy::savePharmacy($pdo,$_POST,$id?:null);setFlash('Pharmacie enregistrée.');}elseif($action==='schedule'){GuardPharmacy::schedule($pdo,$id,$_POST['start_at']??'',$_POST['end_at']??'');setFlash('Garde enregistrée.');}elseif($action==='cancel'){$s=$pdo->prepare('UPDATE pharmacy_guards SET cancelled=1 WHERE id=? AND cancelled=0 AND end_at>?');$s->execute([$id,time()]);setFlash($s->rowCount()?'Garde annulée.':'Garde non modifiable.');}else throw new DomainException('Action invalide.');}catch(DomainException $e){setFlash($e->getMessage(),'error');}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;setFlash('Cette pharmacie existe déjà.','error');}header('Location: /admin/pharmacies-de-garde');exit;}
$pharmacies=$pdo->query('SELECT * FROM pharmacies ORDER BY name,commune')->fetchAll();$edit=null;foreach($pharmacies as $p)if((int)$p['id']===(int)($_GET['modifier']??0))$edit=$p;
$page=max(1,min(100000,(int)($_GET['page']??1)));$rows=$pdo->query('SELECT g.*,p.name,p.commune FROM pharmacy_guards g JOIN pharmacies p ON p.id=g.pharmacy_id ORDER BY g.start_at DESC,g.id DESC LIMIT 51 OFFSET '.(($page-1)*50))->fetchAll();$more=count($rows)>50;if($more)array_pop($rows);$flash=getFlash();require APP_ROOT.'/app/Views/gardes_admin.php';
